// `decizipf:words` bands; only z >= 3.0 is stored, so absence means rare. Rebuild: python3 build-zipf.py --lang en.
// The suggester's bands (3.0 / 3.8 / 5.5, S5) are read on this raw scale: no offset, and no SUBTLEX term (S23).
// POS sets are still SUBTLEX-US Dom_PoS at Percentage_dom_PoS: VA95 Verb/Adverb >= 95%, VA85 >= 85%, ADJ85 Adjective >= 85%.
export const ZIPF_EN = (() => {
    const m = new Map();
    for (const row of PACKED.split(';')) {
        const i = row.indexOf(':'), z = Number(row.slice(0, i)) / 10;
        for (const w of row.slice(i + 1).split(' ')) m.set(w, z);
    }
    return m;
})();
export const POS_VA_STRICT = new Set(VA95.split(' '));
export const POS_VA = new Set([...POS_VA_STRICT, ...VA85.split(' ')]);
export const POS_ADJ = new Set(ADJ85.split(' '));
